UPDATE approval_line
   SET status       = #{status},
       comment      = #{comment},
       processed_at  = #{processedAt}
 WHERE line_id = #{lineId}

UPDATE approval_line
   SET status = 'CURRENT'
 WHERE approval_id = #{approvalId}
   AND step_no = #{stepNo}
   AND status = 'WAITING'

UPDATE approval_line
   SET status = 'SKIPPED'
 WHERE approval_id = #{approvalId}
   AND step_no >= #{fromStepNo}
   AND status IN ('WAITING', 'CURRENT')
